        if self.EPHEMERIS_SOURCE is not None:
            MDPAddEPHEMERIS_SOURCE(builder, EPHEMERIS_SOURCE)
        if self.COMMENT is not None:
            MDPAddCOMMENT(builder, COMMENT)
        MDP = MDPEnd(builder)
        return MDP
